"""Browser projection of server-returned Cycle 12 proofs and supplied states."""
from .web11 import HTML as BASE

STYLE=BASE.split('<style>',1)[1].split('</style>',1)[0]
HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PLN Chess · Fields through time</title><style>'''+STYLE+r'''
.controls{grid-template-columns:repeat(4,minmax(0,1fr))}.wide{grid-column:1/-1}.timeline{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.timeline input{flex:1;min-width:150px}.graph-wrap{overflow:auto;border:1px solid var(--line);border-radius:6px}.graph-wrap svg{display:block;min-width:560px;width:100%;height:auto}.graph-wrap text{font:12px system-ui;fill:var(--text)}.graph-wrap .native{stroke:var(--yes)}.graph-wrap .host{stroke:var(--muted);stroke-dasharray:5 4}.graph-wrap rect{fill:#243748;stroke:var(--line)}.graph-wrap g{cursor:pointer}.graph-wrap g:focus{outline:2px solid var(--accent)}.concept-card{border-left:3px solid var(--line);padding:12px;margin:12px 0;background:#152331}.concept-card p{margin:6px 0}.count{font-variant-numeric:tabular-nums}.boards h3{margin:8px 0}.status.error{color:var(--no)}textarea{width:100%;background:#101923;color:var(--text);border:1px solid var(--line);padding:10px;border-radius:6px}nav{display:flex;gap:20px;flex-wrap:wrap}.cell small{pointer-events:none}button:disabled{opacity:.5;cursor:wait}@media(max-width:700px){.controls{grid-template-columns:1fr 1fr}.controls label:first-child{grid-column:auto}.controls .wide{grid-column:1/-1}.facts{gap:10px}.graph-wrap svg{min-width:560px}}
</style></head><body><main><header><div><div class="eyebrow">PLN Chess · Cycle 12</div><h1>Fields through time</h1><p>Follow a supplied move or sequence through relative influences, partial concepts, and native evidence.</p></div><nav><a href="/fields">Cycle 11 fields ↗</a><a href="/">Legal inspector ↗</a></nav></header>
<form id="inspect-form" class="panel"><div class="controls">
<label>Inspection<select id="view-mode"><option value="snapshot">Before / after move</option><option value="sequence">Supplied sequence</option><option value="concept">Explicit concept roles</option></select></label>
<label>Example<select id="example"></select></label><label>Field evidence<select id="field-model"><option value="trained">Learned</option><option value="empty">Empty</option></select></label><label>Concept evidence<select id="concept-model"><option value="trained">Learned</option><option value="empty">Empty</option></select></label>
<label class="wide">Supplied position · FEN<input id="fen" spellcheck="false" required></label>
<label>Source piece · blank selects all<input id="piece" placeholder="a4" spellcheck="false"></label><label>Supplied move · UCI<input id="move" placeholder="d4f5" spellcheck="false"></label>
<label>Field family<select id="family"><option value="all">All four</option><option value="attack">Attack</option><option value="defense">Defense</option><option value="mobility">Mobility</option><option value="king-exposure">King exposure</option></select></label>
<label>Concept<select id="concept"><option value="all">All concepts</option></select></label>
<label>Unknown cells<input id="unknown" placeholder="d4, e4" spellcheck="false"></label><label>Native proof-node budget<input id="budget" type="number" min="0" max="1000000" value="100000" required></label>
<label>Concept candidate limit<input id="candidate-limit" type="number" min="0" max="64" value="16" required></label>
<details class="wide"><summary>Supplied sequence or explicit roles</summary><p>Sequence events are observations. Explicit roles select a limited conditional query. Neither input asks the system to choose a move.</p><textarea id="supplied" rows="7" aria-label="Supplied sequence or role JSON"></textarea></details>
<div class="actions wide"><button id="run" class="primary" type="submit">Inspect evidence</button><button id="export" type="button" disabled>Export proof package</button><span id="status" class="status" role="status" aria-live="polite">Loading examples…</span></div></div><p id="description"></p></form>
<section class="panel"><h2>Observed states</h2><div class="timeline"><label for="step">Sequence step</label><input id="step" type="range" min="0" max="0" value="0" disabled><output id="step-label" for="step">Snapshot comparison</output></div>
<p id="transition">A supplied move produces a structural successor. Its legality is assessed separately.</p><div class="legend"><span style="--tone:var(--yes)">supported</span><span style="--tone:var(--no)">contradicted</span><span style="--tone:var(--unknown)">unknown</span><span style="--tone:var(--pending)">incomplete</span></div>
<div class="boards"><div><h3 id="before-title">Before</h3><div id="before" class="board" aria-label="Before board"></div></div><div><h3 id="after-title">After supplied move</h3><div id="after" class="board" aria-label="After board"></div></div></div>
<p id="costs" class="status"></p><p id="lineage" class="status"></p></section>
<div class="detail-grid"><section class="panel"><h2>Partial concept interpretations</h2><p>Limited packet conditionals and component fields have separate proofs. A supported packet is not a complete strategic theorem.</p><div id="concepts">Build an inspection to view the selected roles and missing premises.</div></section>
<section class="panel"><h2>Interaction changes</h2><p>These are comparisons of endpoint proofs. Change and persistence labels have no native truth value.</p><div id="changes">No comparison yet.</div></section></div>
<section class="panel"><h2>Dependency graph</h2><p>Solid lines index executed native conditionals. Dashed lines schedule observations or compare results; they carry no truth value. Select an edge to inspect its provenance.</p><p id="graph-count" class="status"></p><div id="graph" class="graph-wrap" aria-label="Dependency graph"></div></section>
<section class="panel"><h2>Separate field relations</h2><p id="relation-count"></p><div class="table-wrap"><table id="relations"><thead><tr><th>State</th><th>Field</th><th>From → target</th><th>Relative offset</th><th>Classification</th><th>Strength</th><th>Confidence</th><th>Evidence</th></tr></thead><tbody></tbody></table></div><button id="more" type="button" hidden>Show 200 more relations</button></section>
<section class="panel"><h2>Selected proof and premises</h2><pre id="proof">Select a field, concept, change, or graph edge.</pre></section>
<footer class="panel"><p>No strategic score, move ranking, universal safety proof, or automatic truth-value propagation is computed. Unknown observations and unsupported implications remain visible.</p></footer>
</main><script>
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';let catalog=null,result=null,rows=[],shown=0;const symbols={White:{King:'♔',Queen:'♕',Rook:'♖',Bishop:'♗',Knight:'♘',Pawn:'♙'},Black:{King:'♚',Queen:'♛',Rook:'♜',Bishop:'♝',Knight:'♞',Pawn:'♟'}};
const square=p=>String.fromCharCode(97+p[0])+(p[1]+1);const show=value=>$('proof').textContent=JSON.stringify(value,null,2);
function text(tag,value,parent,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;parent.append(e);return e}
function choices(){const mode=$('view-mode').value;return mode==='sequence'?catalog.sequences:mode==='concept'?catalog.concept_examples:catalog.examples}
function choose(){const item=choices()[Number($('example').value)];if(!item)return;const mode=$('view-mode').value;$('fen').value=item.initial_fen||item.fen;$('move').value=item.move||'';$('piece').value=mode==='snapshot'?(item.selected_piece_square||''):'';$('unknown').value=(item.unknown_squares||[]).map(s=>typeof s==='string'?s:square(s)).join(', ');$('supplied').value=mode==='sequence'||mode==='concept'?JSON.stringify(item,null,2):'';$('concept').value=mode==='concept'?item.concept:'all';$('description').textContent=item.description||item.scope||'Inspect the supplied role observations and native conditional evidence.';}
function populate(){const select=$('example');select.replaceChildren();choices().forEach((item,i)=>{const o=document.createElement('option');o.value=i;o.textContent=item.id||item.concept+' · '+Object.values(item.roles).join(' / ');select.append(o)});choose()}
function board(id,state){const box=$(id);box.replaceChildren();for(let y=7;y>=0;y--)for(let x=0;x<8;x++){const name=square([x,y]),p=state?.pieces.find(p=>p.square[0]===x&&p.square[1]===y),unknown=state?.unknown_squares.some(s=>s[0]===x&&s[1]===y);const b=document.createElement('button');b.type='button';b.className='cell'+((x+y)%2===0?' dark':'');b.append(document.createTextNode(!state?'·':unknown?'?':p?symbols[p.owner][p.kind]:''));text('small',name,b);const relations=(state?.relations||[]).filter(r=>r.target_square===name);if(relations.length===1)b.classList.add(relations[0].classification);if(p&&state.selected_source_entities.includes(p.id))b.classList.add('selected');b.title=name+(!state?' · state unavailable':unknown?' · unknown contents':p?' · '+p.owner+' '+p.kind:' · empty')+' · '+relations.length+' separate relations';b.setAttribute('aria-label',b.title);b.onclick=()=>{if(relations.length===1)show(relations[0]);else if(p){$('piece').value=name;$('status').textContent='Source selected. Inspect evidence to refresh.'}};box.append(b)}}
function more(){const body=$('relations').querySelector('tbody');for(const [side,r] of rows.slice(shown,shown+200)){const tr=document.createElement('tr');[side,r.family,r.source_square+' → '+r.target_square,r.relative_displacement.join(', '),r.classification,r.raw_stv.strength.toFixed(4),r.raw_stv.confidence.toFixed(4)].forEach(v=>text('td',v,tr,v===r.classification?r.classification:null));const td=text('td','',tr),b=text('button',r.conditional_proof_complete?'Native proof':'Inspect gaps',td);b.type='button';b.dataset.native=String(r.conditional_proof_complete);b.onclick=()=>show(r);body.append(tr)}shown=Math.min(rows.length,shown+200);$('relation-count').textContent=shown+' of '+rows.length+' separate relations shown. The export includes all records.';$('more').hidden=shown>=rows.length}
function graph(data,concepts){const box=$('graph');box.replaceChildren();if(!data){$('graph-count').textContent='No observed graph for this state.';return}const byId=new Map(data.nodes.map(n=>[n.id,n]));const selected=concepts.filter(c=>$('concept').value==='all'||c.concept===$('concept').value);const obs=new Set(selected.map(c=>c.observation_id));const relevant=data.edges.filter(e=>e.origin==='native'&&obs.has(e.source));const picks=[...relevant.slice(0,6),...data.edges.filter(e=>e.origin==='native').slice(0,6),...data.edges.filter(e=>e.predicate==='ExplainsConceptRole').slice(0,4),...data.edges.filter(e=>e.origin!=='native').slice(0,8),...data.edges];const unique=[...new Map(picks.map(e=>[e.id,e])).values()];const edges=unique.slice(0,20);$('graph-count').textContent=data.nodes.length+' nodes · '+data.edges.length+' edges · '+edges.length+' edges displayed. Export retains the complete graph.';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 900 '+Math.max(90,edges.length*74));svg.setAttribute('role','img');svg.setAttribute('aria-label','Proof and observation dependency edges');const label=n=>n.kind==='relative-observation'?'Relative observation':n.kind==='native-field-proposition'?n.family+': '+n.source_square+' → '+n.target_square:n.predicate||n.concept||n.kind;edges.forEach((e,i)=>{const y=i*74+18,g=document.createElementNS(ns,'g');g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',e.predicate+' · '+e.origin);const line=document.createElementNS(ns,'line');Object.entries({x1:250,y1:y+16,x2:650,y2:y+16,class:e.origin==='native'?'native':'host'}).forEach(([k,v])=>line.setAttribute(k,v));g.append(line);[[15,e.source],[650,e.target]].forEach(([x,id])=>{const rect=document.createElementNS(ns,'rect');Object.entries({x,y,width:235,height:34,rx:6}).forEach(([k,v])=>rect.setAttribute(k,v));g.append(rect);const t=document.createElementNS(ns,'text');t.setAttribute('x',x+8);t.setAttribute('y',y+22);t.textContent=label(byId.get(id)).slice(0,32);g.append(t)});const t=document.createElementNS(ns,'text');t.setAttribute('x','265');t.setAttribute('y',y+7);t.textContent=(e.interaction_type||e.predicate).slice(0,42);g.append(t);const sub=document.createElementNS(ns,'text');sub.setAttribute('x','265');sub.setAttribute('y',y+39);sub.textContent=e.origin==='native'?'Native S '+e.truth_value.strength.toFixed(3)+' · C '+e.truth_value.confidence.toFixed(3):e.origin+' · no TV';g.append(sub);g.onclick=()=>show({edge:e,source:byId.get(e.source),target:byId.get(e.target),proof:e.proof_id?data.proofs[e.proof_id]:null});g.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();g.onclick()}};svg.append(g)});box.append(svg)}
function render(){if(!result)return;const temporal=Array.isArray(result.states),step=Number($('step').value),state=temporal?result.states[step]:null;const before=temporal?(step?result.states[step-1].field:state.field):result.before,after=temporal?(step?state.field:null):result.after;const concepts=temporal?state.concepts:result.concepts,changes=temporal?(step?result.transitions[step-1].changes:[]):result.changes,g=temporal?state.graph:result.graph;board('before',before);board('after',after);$('before-title').textContent=temporal?'State S'+Math.max(0,step-1):'Before';$('after-title').textContent=temporal?'State S'+step:'After supplied move';$('step-label').textContent=temporal?'S'+step+' of S'+(result.states.length-1):'Snapshot comparison';const transition=temporal&&step?result.transitions[step-1]:null;$('transition').textContent=temporal?(transition?transition.status+' · '+(transition.move||'missing move')+' · '+transition.gaps.join(' '):'Initial supplied state')+(result.complete_history?' · complete supplied history':' · history contains gaps'):result.candidate?'Supplied edit '+result.candidate.move+' · legality not assessed by concept inference':'Supplied snapshot';$('lineage').textContent=temporal?'Identity segment '+state.segment+' · '+state.source_lineage.length+' supplied events · no planned moves':'';
const cards=$('concepts');cards.replaceChildren();const selected=concepts.filter(c=>$('concept').value==='all'||c.concept===$('concept').value);if(!selected.length)text('p','No selected candidate was enumerated. This is not negative concept evidence.',cards);selected.forEach(c=>{const card=text('div','',cards,'concept-card');text('strong',c.concept+' · '+c.classification,card,c.classification);text('p',c.target+' · S '+c.raw_stv.strength.toFixed(4)+' / C '+c.raw_stv.confidence.toFixed(4),card);text('p','Joint concept proof: incomplete',card);text('p',c.missing_capabilities[0]||c.gaps.join(' '),card);const b=text('button','Inspect roles, premises and proof',card);b.type='button';b.onclick=()=>show(c)});const delta=$('changes');delta.replaceChildren();const changed=changes.filter(c=>c.predicate!=='PersistsAcrossMove');text('p',changed.length+' changed relations · '+(changes.length-changed.length)+' unchanged comparisons · no change TV',delta);for(const c of changed.slice(0,16)){const row=text('p','',delta),r=c.after||c.before,b=text('button',c.predicate+' · '+r.family+' '+r.source_square+' → '+r.target_square,row);b.type='button';b.onclick=()=>show(c)}if(changed.length>16)text('p','All changes are included in the export.',delta);graph(g,concepts);rows=[];for(const [side,field] of [['before',before],['after',after]])if(field)for(const r of field.relations)if($('family').value==='all'||r.family===$('family').value)rows.push([side,r]);shown=0;$('relations').querySelector('tbody').replaceChildren();more();$('costs').textContent=[before,after].filter(Boolean).map((s,i)=>(i?'After':'Before')+': '+s.execution.native_invocations+' executed native operators · '+(s.incremental?.reused_relations||0)+' dependency reuses · '+s.execution.elapsed_seconds.toFixed(2)+' s').join(' | ');$('proof').textContent='Select a field, concept, change, or graph edge.';}
$('view-mode').onchange=populate;$('example').onchange=choose;$('step').oninput=render;$('concept').onchange=()=>{if(result)render()};$('family').onchange=()=>{if(result)render()};$('more').onclick=more;
$('inspect-form').onsubmit=async event=>{event.preventDefault();$('run').disabled=true;$('status').className='status';$('status').textContent='Computing native evidence…';try{const sequence=$('view-mode').value==='sequence';let payload={field_model:$('field-model').value,concept_model:$('concept-model').value,family:$('family').value,max_invocations:Number($('budget').value),max_candidates:Number($('candidate-limit').value)};if(sequence)payload.sequence=JSON.parse($('supplied').value);else{Object.assign(payload,{fen:$('fen').value,piece:$('piece').value.trim(),candidate:$('move').value.trim(),concept:$('concept').value,unknown_squares:$('unknown').value.split(',').map(s=>s.trim()).filter(Boolean)});if($('view-mode').value==='concept'){const c=JSON.parse($('supplied').value);c.fen=payload.fen;c.unknown_squares=payload.unknown_squares;if(payload.candidate)c.move=payload.candidate;payload.cases=[c]}}const response=await fetch(sequence?'/cycle12-evolution':'/cycle12-fields',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw Error(data.error||'Inspection failed');result=data;$('step').max=sequence?data.states.length-1:0;$('step').value=sequence?data.states.length-1:0;$('step').disabled=!sequence;render();$('status').textContent=data.execution.truncated?'Incomplete · inspect proof budgets and gaps':'Complete · conditional and partial scope';$('export').disabled=false}catch(error){$('status').className='status error';$('status').textContent='Error: '+error.message}finally{$('run').disabled=false}};
$('export').onclick=()=>{if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='pln-cycle12-proof-package.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
board('before',null);board('after',null);fetch('/cycle12-catalog').then(r=>{if(!r.ok)throw Error('Examples unavailable');return r.json()}).then(data=>{catalog=data;for(const c of data.concepts){const o=document.createElement('option');o.value=c;o.textContent=c;$('concept').append(o)}populate();$('status').textContent='Ready · select a position or supplied sequence'}).catch(e=>{$('status').textContent='Error: '+e.message});
</script></body></html>'''
